    const SGALL = {"case-koynx":{"title":"One guide for mobile, web and admin","intro":"The KOYNX style guide was written during the rebrand from Hillcross Pay, so the new identity and the product UI were defined together and shared by every surface.","swatches":[{"hex":"#E74C3C","name":"KOYNX red"},{"hex":"#B8323F","name":"Deep red"},{"hex":"#111111","name":"Ink"},{"hex":"#7C3AED","name":"Personal savings"},{"hex":"#9A3412","name":"Smart Esusu"},{"hex":"#166534","name":"Stokvel"},{"hex":"#2563EB","name":"Payouts"}],"type":[{"role":"Display","size":"28px","weight":"800","sample":"Lets Get You Started"},{"role":"Heading","size":"20px","weight":"700","sample":"Savings Management"},{"role":"Body","size":"15px","weight":"500","sample":"Monitor and manage all savings accounts"},{"role":"Label","size":"11px","weight":"700","sample":"PENDING KYC"}],"components":["Buttons","Inputs & PIN keypad","Stat cards","Savings product cards","Data tables","Filters & search","Status pills","KYC tier badges","Log tabs","Modals","Success states","Side navigation"],"build":[{"n":"01","t":"Brand first: the KOYNX name, red and gear mark were set as tokens before any screen was redrawn."},{"n":"02","t":"Mobile next: savings, Esusu, Stokvel and PIN flows defined the core components."},{"n":"03","t":"Web and admin last: the same tokens and components were extended with tables, filters and logs."}],"maintain":[{"n":"01","t":"Every new screen starts from library components, not from copies of old screens."},{"n":"02","t":"When a pattern changes, such as KYC tiers or log tabs, the component is updated and every screen follows."},{"n":"03","t":"Product colours stay fixed so members and staff read Personal, Esusu and Stokvel the same way."}]},"case-hcportal":{"title":"One guide behind three portals","intro":"The HillCross guide serves the student, lecturer and admin portals. It was built alongside the student portal and maintained as the other two were added.","swatches":[{"hex":"#A83232","name":"HillCross red"},{"hex":"#C41E3A","name":"Accent red"},{"hex":"#111827","name":"Ink"},{"hex":"#6B7280","name":"Muted text"},{"hex":"#F3F4F6","name":"Surface"},{"hex":"#16A34A","name":"Success"},{"hex":"#F59E0B","name":"Pending"}],"type":[{"role":"Display","size":"28px","weight":"800","sample":"Welcome back, student"},{"role":"Heading","size":"20px","weight":"700","sample":"Programme Selection"},{"role":"Body","size":"15px","weight":"500","sample":"Your application is under review"},{"role":"Label","size":"11px","weight":"700","sample":"STEP 3 OF 5"}],"components":["Sidebar navigation","Metric cards","Course cards","Stepper","Form fields & uploads","Status chips","Tabs","Calendar views","Side panels","Modals","Empty & locked states","Success states"],"build":[{"n":"01","t":"Foundations: red, neutral greys, one type scale and a spacing grid were set before the first module."},{"n":"02","t":"Components were built from real student screens, then reused across all 13 flows."},{"n":"03","t":"States such as empty, locked, pending review and success were designed once and applied everywhere."}],"maintain":[{"n":"01","t":"Changes are made in the library and flow into the student, lecturer and admin portals."},{"n":"02","t":"New modules like finance and mentorship were assembled from existing parts first."},{"n":"03","t":"Each release was reviewed against the guide so the three portals stay consistent."}]},"case-blissbill":{"title":"A gold-on-pattern identity, light and dark","intro":"BlissBill’s guide pairs a warm gold with bold African patterns, and every component was defined for both light and dark mode.","swatches":[{"hex":"#D8A830","name":"Bliss gold"},{"hex":"#F0D890","name":"Soft gold"},{"hex":"#307890","name":"Teal"},{"hex":"#111111","name":"Ink"},{"hex":"#FFFFFF","name":"Surface"}],"type":[{"role":"Display","size":"28px","weight":"800","sample":"Welcome to BlissBill"},{"role":"Heading","size":"20px","weight":"700","sample":"Create Account"},{"role":"Body","size":"15px","weight":"500","sample":"Pay your bills in seconds"},{"role":"Label","size":"11px","weight":"700","sample":"VIRTUAL CARD"}],"components":["Buttons","Inputs","Onboarding carousel","Bill cards","Virtual card","Transaction rows","Bottom navigation","Success states"],"build":[{"n":"01","t":"Brand: gold and the pattern set the tone for splash and onboarding."},{"n":"02","t":"Core flows: login, home, bills and virtual card defined the components."},{"n":"03","t":"Dark mode: every component was given a dark counterpart from the same tokens."}],"maintain":[{"n":"01","t":"Light and dark values live side by side, so a change lands in both modes."},{"n":"02","t":"New bill types reuse the same card and confirmation pattern."},{"n":"03","t":"Handoff files document each component state for developers."}]},"case-laundromate":{"title":"Clean blue with a warm accent","intro":"Laundromate’s guide uses a fresh blue for trust and a coral accent for actions, with one colour per service so orders read at a glance.","swatches":[{"hex":"#30A8F0","name":"Laundromate blue"},{"hex":"#3090F0","name":"Deep blue"},{"hex":"#F07848","name":"Coral"},{"hex":"#16A34A","name":"Ironing"},{"hex":"#111111","name":"Ink"}],"type":[{"role":"Display","size":"28px","weight":"800","sample":"Lets begin"},{"role":"Heading","size":"20px","weight":"700","sample":"Select your service"},{"role":"Body","size":"15px","weight":"500","sample":"We collect, clean and deliver"},{"role":"Label","size":"11px","weight":"700","sample":"MINIMUM ORDER"}],"components":["Buttons","Inputs with validation","Service cards","Item counters","Bottom sheets","Address & map","Order summary","Receipt"],"build":[{"n":"01","t":"Brand: blue, coral and the washing-machine mark came first."},{"n":"02","t":"Booking flow: service cards, counters and sheets were built for the core order."},{"n":"03","t":"Checkout: summary and receipt reuse the same rows and totals."}],"maintain":[{"n":"01","t":"Each service keeps its colour across cards, summaries and receipts."},{"n":"02","t":"New markets only swap currency and city data, not components."},{"n":"03","t":"Validation states are shared by every form."}]},"case-wemove":{"title":"Energy yellow on deep teal","intro":"WeMove’s guide uses a high-energy yellow over deep teal, with reward artwork that follows African-inspired motifs.","swatches":[{"hex":"#FFC018","name":"Move yellow"},{"hex":"#186060","name":"Deep teal"},{"hex":"#603018","name":"Earth brown"},{"hex":"#111111","name":"Ink"},{"hex":"#FFFFFF","name":"Surface"}],"type":[{"role":"Display","size":"28px","weight":"800","sample":"Ready to move?"},{"role":"Heading","size":"20px","weight":"700","sample":"Quick Burst"},{"role":"Body","size":"15px","weight":"500","sample":"Finish faster, earn more mints"},{"role":"Label","size":"11px","weight":"700","sample":"LEGENDARY"}],"components":["Buttons","Range selectors","Progress bars","Workout cards","Timers","Reward mints","Bottom navigation","Success states"],"build":[{"n":"01","t":"Research and brand set the yellow, teal and reward style."},{"n":"02","t":"Onboarding defined the selectors and progress components."},{"n":"03","t":"Workouts and rewards reused them with timers and mint cards."}],"maintain":[{"n":"01","t":"Mint tiers share one card with three rarity treatments."},{"n":"02","t":"New workouts reuse the card and timer components."},{"n":"03","t":"Progress always uses the same bar so goals read the same everywhere."}]}};
    const STALL = {"case-koynx":{"title":"How a college payment app became a savings platform","beats":[["Where it started","A product built for one college","KOYNX began as Hillcross Pay, a financial services product designed in 2025. In January 2026 the brief changed: rebrand it and take it to a broader South African market.","/assets/kx-m01.webp","top center","A new member’s first dashboard"],["Who it is for","People saving alone and together","Some save towards their own goals. Others pay into a rotating Esusu pot or a stokvel through cash, notebooks and WhatsApp. All of them needed to see every rand and trust where it goes.","/assets/kx-m12.webp","top center","Personal savings goals"],["What changed","A new name and three ways to save","The rebrand brought a new identity and split saving into Personal, Smart Esusu and Stokvel, each with its own colour and flow.","/assets/kx-m07.webp","top center","The savings hub, active member"],["Why it works","Every rand on record","Deposits, contributions and payouts are logged in one list, so members can always see where their money went.","/assets/kx-m29.webp","top center","Transactions"]]},"case-hcportal":{"title":"From first application to exam day","beats":[["The brief","Three users, one university","HillCross needed connected portals for students, lecturers and administrators. The student portal came first, and its design system set the rules the other two would follow.","/assets/portal-8.webp","top center","Returning student sign in"],["Getting in","Applying without the paperwork","A new student creates an account in three steps. Their nationality sets the fee plan, their ID is checked against Home Affairs, and the portal calculates a preliminary APS score as results are entered.","/assets/portal-15.webp","top center","Academic history with live APS score"],["Waiting","Always knowing where you stand","After submitting, the student sees the auto-check results, an assigned reviewer and a live timeline. The decision arrives as an admission offer with an accept-by date and the Year 1 fee breakdown.","/assets/portal-21.webp","top center","Admission offer"],["Everyday study","A dashboard that changes with the student","Before admission, academic modules stay locked. During a break, friendly empty states take over. Once the semester starts, the dashboard fills with study focus, graded work and the week ahead.","/assets/portal-27.webp","top center","Returning student, active semester"],["The difference","An assistant that plans the day","AI Assist reads past study sessions and suggests what to do first, with time and confidence estimates. On assignments it shows the rubric and offers a draft review.","/assets/portal-29.webp","top center","Personalised study plan"],["Exam day","Fair exams from anywhere","Before a proctored exam, the lobby checks camera, microphone and presence. During the exam, a timer, invigilator video, question navigator and autosave keep the student focused.","/assets/portal-57.webp","top center","Exam lobby system check"],["What's next","Launching soon","The student portal is designed end to end and preparing for launch. The lecturer and admin portals follow on the same design system.","/assets/portal-40.webp","top center","Semester started, week 1"]]}};
